func TestAdd(t *testing.T) {
	if add(2, 3) != 5 {
		t.Fatalf("add(2, 3) = %d, want 5", add(2, 3))
	}
}

func TestClamp(t *testing.T) {
	tests := []struct {
		value int
		lower int
		upper int
		want  int
	}{
		{value: 5, lower: 0, upper: 10, want: 5},
		{value: -3, lower: 0, upper: 10, want: 0},
		{value: 42, lower: 0, upper: 10, want: 10},
		{value: 0, lower: 0, upper: 10, want: 0},
		{value: 10, lower: 0, upper: 10, want: 10},
	}

	for _, tt := range tests {
		if got := clamp(tt.value, tt.lower, tt.upper); got != tt.want {
			t.Errorf("clamp(%d, %d, %d) = %d, want %d", tt.value, tt.lower, tt.upper, got, tt.want)
		}
	}
}

